20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        String householdId = owner.getHouseholdId();
23	        if (householdId == null || householdId.isBlank()) {
24	            owner.setHouseholdSize(1);
25	            return;
26	        }
27	        int count = 1; // include the owner being created, not yet persisted
